  Files.write(new File(c.getFilesDir(),"legacy-download-info.json").toPath(),new org.json.JSONObject().put("uri",uri.toString()).put("title",downloadedTitle).put("oldRejectedBytes",broken.getBytes(StandardCharsets.UTF_8).length).put("oldVersionErrorReproduced",true).toString().getBytes(StandardCharsets.UTF_8));

